import { n as listarCursos } from "../../../chunks/cursos2.js";
import { t as exigirGabinete } from "../../../chunks/acceso.js";
import { n as ESTADOS_CASO } from "../../../chunks/guia.js";
import { d as resumenTablero, s as listarCasos } from "../../../chunks/gabinete.js";
//#region src/routes/gabinete/+page.server.ts
var load = async ({ locals }) => {
	await exigirGabinete(locals.usuario);
	const [resumen, derivados, cursos] = await Promise.all([
		resumenTablero(),
		listarCasos({ estado: "derivado" }),
		listarCursos().catch(() => [])
	]);
	return {
		resumen,
		derivados: derivados.map((d) => ({
			...d.caso,
			responsable: d.responsable
		})),
		cursos: cursos.map((c) => ({
			id: c.id,
			nombre: c.displayname || c.fullname
		})),
		estados: ESTADOS_CASO
	};
};
//#endregion
export { load };
